from pathlib import Path
import base64,json,html as html_escape
root=Path(__file__).resolve().parents[2]
a=root/'lfma/portal/prototypes/client-perspective-directions'
config=json.loads((Path(__file__).parent/'campaign-portal-config.json').read_text())
if config['mode']!='LOCAL_VISUAL_REVIEW_ONLY' or config['runtime_connected'] is not False: raise ValueError('Visual-only configuration required')
if config['client']['tenant_id']!='phillips': raise ValueError('New client facts/access require independent validation; do not inherit Phillips proof')
if config['plan']['actual_spent'] is not None or config['plan']['remaining'] is not None: raise ValueError('Current actual spend is unverified')
demo=json.loads((Path(__file__).parent/config['demo_fixture']).read_text())
if demo['mode']!='SYNTHETIC_ONLY' or demo['counted_in_actual_totals'] is not False: raise ValueError('Synthetic fixture only')
# Reuse the approved-for-review MA/LFMA family; no existing live portal changes.
existing=(a/'03-workspace.html').read_text()
css=existing.split('<style>',1)[1].split('</style>',1)[0]
creative=base64.b64encode((root/'lfma/portal/prototypes/phillips-current/review-asset.jpg').read_bytes()).decode()
logo=base64.b64encode((root/config['brand']['logo_asset']).read_bytes()).decode()
history_rows=json.loads((Path(__file__).parent/'deidentified-dispatch-history.json').read_text())
if history_rows['coverage']!='INCOMPLETE' or history_rows['dispatch_evidence_events']!=135 or history_rows['private_bytes_verified_locally'] is not True: raise ValueError('Verified minimized historical source required')
history_summary=json.loads((Path(__file__).parent/'historical-summary.json').read_text())
if history_summary['coverage']!='INCOMPLETE' or history_summary['current_campaign_totals'] is not False: raise ValueError('Historical evidence remains separate and incomplete')
historical=json.loads((Path(__file__).parent/'historical-creative/manifest.json').read_text())
for item in historical['assets']:
    raw=(Path(__file__).parent/'historical-creative'/item['filename']).read_bytes()
    import hashlib
    if hashlib.sha256(raw).hexdigest()!=item['sha256']: raise ValueError('Historical image identity changed')
    item['image']='data:image/'+('jpeg' if item['filename'].endswith('.jpeg') else 'png')+';base64,'+base64.b64encode(raw).decode()
